import{_ as a,a0 as n,w as l,s as i,ao as c,I as p,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"配置 Linux 的訪問控制列表(ACL) | LCTT x X-CMD","titleTemplate":false,"description":"配置 Linux 的訪問控制列表(ACL) | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"配置 Linux 的訪問控制列表(ACL) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"配置 Linux 的訪問控制列表(ACL) | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140818 How to configure Access Control Lists (ACLs) on Linux","title":"配置 Linux 的訪問控制列表(ACL)","tag":"201410","desc":""},"relativePath":"201410/20140818 How to configure Access Control Lists (ACLs) on Linux.md","filePath":"[post].md"}'),d={name:"201410/20140818 How to configure Access Control Lists (ACLs) on Linux.md"};function u(L,t,m,f,C,A){const r=n("Link");return l(),i("div",null,[t[13]||(t[13]=c(`<h1 id="配置-linux-的訪問控制列表-acl" tabindex="-1">配置 Linux 的訪問控制列表(ACL) <a class="header-anchor" href="#配置-linux-的訪問控制列表-acl" aria-label="Permalink to “配置 Linux 的訪問控制列表(ACL)”">​</a></h1><p>使用擁有權限控制的Liunx，工作是一件輕鬆的任務。它可以定義任何user,group和other的權限。無論是在桌面電腦或者不會有很多用户的虛擬Linux實例，或者當用户不願意分享他們之間的文件時，這樣的工作是很棒的。然而，如果你是在一個大型組織，你運行了NFS或者Samba服務給不同的用户，然後你將會需要靈活的挑選並設置很多複雜的配置和權限去滿足你的組織不同的需求。</p><p>Linux（和其他Unix等POSIX兼容的操作系統）有一種被稱為訪問控制列表(ACL)的權限控制方法，它是一種權限分配之外的普遍範式。例如，默認情況下你需要確認3個權限組：owner、group和other。而使用ACL，你可以增加權限給其他用户或組別，而不單只是簡單的&quot;other&quot;或者是擁有者不存在的組別。可以允許指定的用户A、B、C擁有寫權限而不再是讓他們整個組擁有寫權限。</p><p>ACL支持多種Linux文件系統，包括ext2, ext3, ext4, XFS, Btfrs, 等。如果你不確定你的文件系統是否支持ACL，請參考文檔。</p><h3 id="在文件系統使acl生效" tabindex="-1">在文件系統使ACL生效 <a class="header-anchor" href="#在文件系統使acl生效" aria-label="Permalink to “在文件系統使ACL生效”">​</a></h3><p>首先，我們需要安裝工具來管理ACL。</p><p>Ubuntu/Debian 中:</p><pre><code>$ sudo apt-get install acl
</code></pre><p>CentOS/Fedora/RHEL 中:</p><pre><code># yum -y install acl
</code></pre><p>Archlinux 中:</p><pre><code># pacman -S acl
</code></pre><p>出於演示目的，我將使用ubuntu server版本，其他版本類似。</p><p>安裝ACL完成後，需要激活我們磁盤分區的ACL功能，這樣我們才能使用它。</p><p>首先，我們檢查ACL功能是否已經開啓。</p><pre><code>$ mount
</code></pre><p><img src="https://farm4.staticflickr.com/3859/14768099340_eab7b53e28_z.jpg" alt=""></p><p>你可以注意到，我的root分區中ACL屬性已經開啓。萬一你沒有開啓，你需要編輯/etc/fstab文件，在你需要開啓ACL的分區的選項前增加acl標記。</p><p><img src="https://farm6.staticflickr.com/5566/14931771056_b48d5daae2_z.jpg" alt=""></p><p>現在我們需要重新掛載分區（我喜歡完全重啓，因為我不想丟失數據），如果你對其它分區開啓ACL，你必須也重新掛載它。</p><pre><code>$ sudo mount / -o remount
</code></pre><p>乾的不錯！現在我們已經在我們的系統中開啓ACL，讓我們開始和它一起工作。</p><h3 id="acl-範例" tabindex="-1">ACL 範例 <a class="header-anchor" href="#acl-範例" aria-label="Permalink to “ACL 範例”">​</a></h3><p>基礎ACL通過兩條命令管理：<strong>setfacl</strong>用於增加或者修改ACL，<strong>getfacl</strong>用於顯示分配完的ACL。讓我們來做一些測試。</p><p>我創建一個目錄/shared給一個假設的用户，名叫freeuser</p><pre><code>$ ls -lh /
</code></pre><p><img src="https://farm4.staticflickr.com/3869/14954774565_49456360be_z.jpg" alt=""></p><p>我想要分享這個目錄給其他兩個用户test和test2，一個擁有完整權限，另一個只有讀權限。</p><p>首先，為用户test設置ACL：</p><pre><code>$ sudo setfacl -m u:test:rwx /shared
</code></pre><p>現在用户test可以隨意創建文件夾，文件和訪問在/shared目錄下的任何地方。</p><p><img src="https://farm4.staticflickr.com/3924/14768099439_44780ff03b_z.jpg" alt=""></p><p>現在我們增加只讀權限給用户test2:</p><pre><code>$ sudo setfacl -m u:test2:rx /shared
</code></pre><p>注意test2讀取目錄需要執行(x)權限</p><p><img src="https://farm4.staticflickr.com/3918/14768215947_4cd86104d3_z.jpg" alt=""></p><p>讓我來解釋下setfacl命令格式：</p><ul><li><strong>-m</strong> 表示修改ACL。你可以增加新的，或修改存在的ACL</li><li><strong>u:</strong> 表示用户。你可以使用 <strong>g</strong> 來設置組權限</li><li><strong>test</strong> 用户名</li><li><strong>:rwx</strong> 需要設置的權限。</li></ul><p>現在讓我向你展示如何讀取ACL：</p><pre><code>$ ls -lh /shared
</code></pre><p><img src="https://farm6.staticflickr.com/5591/14768099389_9a7f3a6bf2_z.jpg" alt=""></p><p>你可以注意到，正常權限後多一個+標記。這表示ACL已經設置成功。要具體看一下ACL，我們需要運行：</p><pre><code>$ sudo getfacl /shared
</code></pre><p><img src="https://farm4.staticflickr.com/3839/14768099289_81bd9d21a4_z.jpg" alt=""></p><p>最後，如果你需要移除ACL：</p><pre><code>$ sudo setfacl -x u:test /shared
</code></pre><p><img src="https://farm4.staticflickr.com/3910/14768215837_d5306fe5bf_z.jpg" alt=""></p><p>如果你想要立即擦除所有ACL條目：</p><pre><code>$ sudo setfacl -b /shared
</code></pre><p><img src="https://farm4.staticflickr.com/3863/14768099130_a7d175f067_z.jpg" alt=""></p><p>最後，在設置了ACL文件或目錄工作時，cp和mv命令會改變這些設置。在cp的情況下,需要添加“p”參數來複制ACL設置。如果這不可行，它將會展示一個警告。mv默認移動ACL設置，如果這也不可行，它也會向您展示一個警告。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用ACL讓在你想要分享的文件上擁有更多的能力和控制，特別是在NFS/Samba服務。此外，如果你的主管共享主機，這個工具是必備的。</p><hr>`,54)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(r,{href:"http://xmodulo.com/2014/08/configure-access-control-lists-acls-linux.html"},{default:s(()=>[...t[0]||(t[0]=[e("http://xmodulo.com/2014/08/configure-access-control-lists-acls-linux.html",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),o(r,{href:"http://xmodulo.com/author/valerio"},{default:s(()=>[...t[2]||(t[2]=[e("Christopher Valerio",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),o(r,{href:"http://www.vicyu.net"},{default:s(()=>[...t[3]||(t[3]=[e("VicYu",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const _=a(d,[["render",u]]);export{h as __pageData,_ as default};
